private val scoreReason = Regex("""Automatic: score ([0-9]+) — ([a-zA-Z0-9][a-zA-Z0-9._-]{0,63}=[\s\S]+ \(\+[0-9]+\))(?: and ([0-9]+) more)?""")

/** Deck JSON stores canonical reasons. Render only known forms, leaving rule values and imported text alone. */
fun displaySelectionReason(reason: String): String = when (reason) {
    "Choose a profile" -> LauncherCopy.Choose.text()
    "Selected an available profile" -> LauncherCopy.Available.text()
    "Previous or Next exits the game" -> LauncherCopy.ExitGame.text()
    "Default profile" -> LayoutCopy.DefaultReason.text()
    "Manually selected" -> LayoutCopy.ManualSelection.text()
    "Manually selected and pinned" -> LayoutCopy.ManualSelectionPinned.text()
    "Selected automatically" -> LayoutCopy.AutomaticSelection.text()
    "Manually pinned" -> LayoutCopy.ManualPin.text()
    "Last selected by manual pin (now unpinned)" -> LayoutCopy.LastPin.text()
    "Manually cycled" -> LayoutCopy.ManualCycle.text()
    "Manually cycled and pinned" -> LayoutCopy.ManualCyclePinned.text()
    "Default selected after profile deletion" -> LayoutCopy.DeletedReason.text()
    "Local Teams call" -> LayoutCopy.TeamsReason.text()
    "Automatic: default profile (no matching rules)" -> LayoutCopy.NoMatches.text()
    "Automatic: matched an app mapping" -> LayoutCopy.MatchedApp.text()
    else -> scoreReason.matchEntire(reason)?.let { match ->
        val (score, details, more) = match.destructured
        val suffix = if (more.isEmpty()) "" else {
            val count = more.toIntOrNull()?.takeIf { it > 0 } ?: return@let null
            " " + LayoutCopy.MoreRules.text(count)
        }
        LayoutCopy.ScoreReason.text(score, details + suffix)
    } ?: reason
}
